function chooseWeapon(id){if(mode==='online')command('select-weapon',{weaponId:id});else{saves?.markDirty();selectWeapon(state,state.activePlayer,id);}sync();render();}
for(const select of [document.querySelector('#weapon-select'),document.querySelector('#fullscreen-weapon'),document.querySelector('#mobile-weapon')]){Object.values(WEAPON_REGISTRY).forEach(weapon=>{const option=document.createElement('option');option.value=weapon.id;option.textContent=weapon.label;select.append(option);});select.addEventListener('change',event=>chooseWeapon(event.target.value));}
