function syncTankHud(){[0,1].forEach(index=>{const health=tankHealth(index),bar=document.querySelector(index?'#health-bar-right':'#health-bar-left');document.querySelector(index?'#health-right':'#health-left').textContent=health;bar.style.width=`${health}%`;bar.style.background=health>50?'#78d294':health>0?'#ffc65c':'#df604f';});}
