function syncImpactHud(){if((state.impactSerial||0)<lastImpactSerial)lastImpactSerial=0,combatEffects=[];if(state.lastImpact?.serial>lastImpactSerial){if(mode==='solo'&&state.lastImpact.owner===0&&(state.lastImpact.affected||[]).some(item=>item.tank===1&&item.healthDamage>0))soloStatistics.hits+=1;lastImpactSerial=state.lastImpact.serial;triggerImpactEffect(state.lastImpact);const callout=document.querySelector('#impact-callout'),damage=Number(state.lastImpact.totalDamage)||0;callout.textContent=damage?`${damage} DAMAGE!`:'BOOM!';callout.classList.remove('show');void callout.offsetWidth;callout.classList.add('show');}}
function syncArenaHud(){const active=state.activePlayer===1?1:0,tank=state.tanks?.[active]||{},concealed=Boolean(tank.concealed),angle=concealed||!Number.isFinite(tank.angle)?'—':`${tank.angle}°`,power=concealed||!Number.isFinite(tank.power)?'—':`${tank.power}%`;document.querySelector('#active-player').textContent=playerLabel(active);for(const id of ['#angle','#fullscreen-angle','#mobile-angle'])document.querySelector(id).textContent=angle;for(const id of ['#power','#fullscreen-power','#mobile-power'])document.querySelector(id).textContent=power;document.querySelector('#active-flag').textContent=state.phase==='game-over'?(state.draw?'Draw':`${playerLabel(state.winner??0)} wins`):`${playerLabel(active)} turn`;arena.dataset.active=active;arena.dataset.phase=state.phase;const description=index=>{const hidden=state.tanks?.[index]?.concealed?' and position concealed':'';const shield=(state.activeEffects?.[index]||[]).find(effect=>effect.effect==='absorb');return `${hidden}${shield?` and shield with ${shield.remainingTurns??0} turns and ${shield.remainingCapacity??0} capacity`:' and no shield'}`;};canvas.setAttribute('aria-label',`Battle Tanks arena. ${playerLabel(active)} is active. Player 1 has ${tankHealth(0)} health${description(0)}; ${playerLabel(1)} has ${tankHealth(1)} health${description(1)}.`);}
function syncEffectsHud(){const shields=[0,1].map(index=>{const shield=(state.activeEffects?.[index]||[]).find(effect=>effect.effect==='absorb');return shield?`${playerLabel(index)} shield: ${shield.remainingTurns??0} turns, ${shield.remainingCapacity??0} capacity`:'';}).filter(Boolean),announcement=mode==='solo'?(state.announcement||'').replaceAll('Player 2','CPU'):state.announcement;status.textContent=[state.opponentConcealed?'Opponent concealed.':announcement,...shields].filter(Boolean).join(' ');}
function announceStateChanges(){const messages=[];if(state.lastImpact?.serial>announcedImpactSerial){announcedImpactSerial=state.lastImpact.serial;const absorbed=(state.lastImpact.affected||[]).reduce((sum,item)=>sum+(Number(item.absorbedDamage)||0),0);if(absorbed)messages.push(`Shields absorbed ${absorbed} damage.`);}if(state.announcement&&state.announcement!==previousAnnouncement)messages.push(state.announcement);[0,1].forEach(index=>{const health=tankHealth(index);if(health>previousHealth[index])messages.push(`Player ${index+1} healed ${health-previousHealth[index]} health.`);const oldShield=previousEffects[index].find(effect=>effect.effect==='absorb'),shield=(state.activeEffects?.[index]||[]).find(effect=>effect.effect==='absorb');if(oldShield&&shield&&shield.remainingCapacity<oldShield.remainingCapacity)messages.push(`Player ${index+1} shield absorbed ${oldShield.remainingCapacity-shield.remainingCapacity} damage.`);previousEffects[index].forEach(effect=>{if(!(state.activeEffects?.[index]||[]).some(current=>current.id===effect.id))messages.push(`${POWER_UP_CATALOG[effect.id]?.label||'Effect'} expired for Player ${index+1}.`);});const weapon=state.equippedWeapons?.[index]||'shell';if(weapon!==previousWeapons[index])messages.push(`Player ${index+1} selected ${WEAPON_REGISTRY[weapon]?.label||'Standard shell'}.`);previousHealth[index]=health;previousEffects[index]=(state.activeEffects?.[index]||[]).map(effect=>({...effect}));previousWeapons[index]=weapon;});previousAnnouncement=state.announcement||'';if(messages.length)document.querySelector('#pickup-announcement').textContent=messages.join(' ');}
function syncControls(){const cpuTurn=mode==='solo'&&state.activePlayer===1,locked=savePaused||state.phase!=='aiming'||cpuTurn||(mode==='online'&&(mySide!==state.activePlayer||state.paused));document.querySelectorAll('[data-action],[data-move-direction]').forEach(button=>button.disabled=locked);fire.disabled=locked;fullscreenFire.disabled=locked;mobileFire.disabled=locked;syncInventory(locked);const gameOver=state.phase==='game-over',health=Math.min(...(state.tanks||[]).map(tank=>Math.max(0,Number(tank.health)||0))),danger=1-health/STARTING_HEALTH,paused=Boolean(state.paused)||savePaused;if(paused!==presentedPauseState){presentedPauseState=paused;events.emit('game:paused',{paused});}const progressState=`${state.matchId}:${state.phase}:${danger.toFixed(2)}`;if(!gameOver&&progressState!==presentedProgressState){presentedProgressState=progressState;events.emit('game:progressed',{intensity:state.phase==='projectile-flight'?.82:.32+danger*.35,danger});}resultLayer.hidden=!gameOver;if(gameOver){const resultKey=`${state.matchId??'local'}:${state.winner??'draw'}`;if(resultKey!==presentedResultEvent){presentedResultEvent=resultKey;const won=!state.draw&&(mode!=='online'?state.winner===0:state.winner===mySide);events.emit('game:completed',{outcome:state.draw?'draw':won?'win':'loss',shots:state.shots});}document.querySelector('#result-title').textContent=state.draw?'Draw!':`${playerLabel(state.winner)} wins!`;document.querySelector('#result-summary').textContent=state.draw?`Both tanks fell after ${state.shots} shots.`:mode==='solo'?`Battle ended after ${state.shots} shots · your accuracy ${soloStatistics.shots?Math.floor(soloStatistics.hits*100/soloStatistics.shots):0}%.`:`Victory secured in ${state.shots} shots with ${state.hits} hits.`;}}
function sync(){syncAcquisitionEvents();syncTankHud();syncImpactHud();syncArenaHud();syncEffectsHud();announceStateChanges();syncControls();}

function sendOnline(message){if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify(message));}
function command(type,extra={}){sendOnline({type,matchId:state.matchId,turnId:state.turnId,...extra});}
function cancelAiTurn(){clearTimeout(aiTimer);aiTimer=null;aiThinking=false;}
function useAiPowerUps(){const used=[];for(const id of cpu.planPowerUps(state,1)){const result=activatePowerUp(state,1,id);if(result)used.push(POWER_UP_CATALOG[id].label);}return used;}
function finishAiTurn(){if(mode!=='solo'||state.phase!=='aiming'||state.activePlayer!==1||currentPowerCard){cancelAiTurn();return;}const used=useAiPowerUps();if(used.length)saves?.markDirty();const plan=cpu.planShot(state,1),tank=state.tanks[1];if(!plan){cancelAiTurn();return;}saves?.markDirty();tank.angle=plan.angle;tank.power=plan.power;selectWeapon(state,1,plan.weaponId);state.announcement=used.length?`CPU used ${used.join(', ')} and locked angle ${plan.angle}° at ${plan.power}% power.`:`CPU locked angle ${plan.angle}° at ${plan.power}% power.`;sync();render();aiTimer=setTimeout(()=>{aiThinking=false;aiTimer=null;if(mode==='solo'&&state.phase==='aiming'&&state.activePlayer===1&&!currentPowerCard){const weapon=state.equippedWeapons?.[1]||'shell';if(fireProjectile(state)){saves?.markDirty();events.emit('battletanks:shot-fired',{weapon,side:1});}sync();render();}},380);}
function animateAiMove(plan){const steps=Math.max(1,Math.ceil(plan.amount/18)),stepAmount=plan.amount/steps;let remaining=steps;const advance=()=>{if(mode!=='solo'||state.phase!=='aiming'||state.activePlayer!==1||currentPowerCard){cancelAiTurn();return;}if(moveTank(state,plan.direction,stepAmount))saves?.markDirty();remaining-=1;state.announcement='CPU is repositioning…';sync();render();if(remaining>0)aiTimer=setTimeout(advance,75);else aiTimer=setTimeout(finishAiTurn,220);};advance();}
function scheduleAiTurn(){if(mode!=='solo'||state.phase!=='aiming'||state.activePlayer!==1||aiThinking||currentPowerCard)return;aiThinking=true;status.textContent='CPU is choosing a new position…';aiTimer=setTimeout(()=>{if(mode!=='solo'||state.phase!=='aiming'||state.activePlayer!==1){cancelAiTurn();return;}const movement=cpu.planMove(state,1);if(movement?.amount>0)animateAiMove(movement);else finishAiTurn();},420);}
function act(action){if(savePaused||currentPowerCard||mode==='solo'&&state.activePlayer===1)return;if(mode==='online'){if(action==='forward'||action==='backward')command('move',{direction:action});else{const tank=state.tanks[state.activePlayer];if(!tank||tank.concealed)return;const angle=tank.angle+(action==='aim-up'?2:action==='aim-down'?-2:0),power=tank.power+(action==='power-up'?5:action==='power-down'?-5:0);command('aim',{angle:Math.max(10,Math.min(80,angle)),power:Math.max(20,Math.min(100,power))});}if(performance.now()-lastControlEventAt>120){lastControlEventAt=performance.now();events.emit(action==='forward'||action==='backward'?'battletanks:tank-moved':'battletanks:control-adjusted',{action});}return;}saves?.markDirty();if(action==='forward'||action==='backward')moveTank(state,action);else if(action==='aim-up')adjustAim(state,2);else if(action==='aim-down')adjustAim(state,-2);else if(action==='power-up')adjustPower(state,5);else if(action==='power-down')adjustPower(state,-5);if(performance.now()-lastControlEventAt>120){lastControlEventAt=performance.now();events.emit(action==='forward'||action==='backward'?'battletanks:tank-moved':'battletanks:control-adjusted',{action});}sync();render();}
function resetSoloStatistics(){soloStatistics={shots:0,hits:0};}
function moveAction(direction){return direction==='left'?(state.activePlayer?'forward':'backward'):(state.activePlayer?'backward':'forward');}document.querySelectorAll('[data-move-direction]').forEach(button=>button.addEventListener('click',()=>act(moveAction(button.dataset.moveDirection))));document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>act(button.dataset.action)));function shoot(){if(savePaused||currentPowerCard||mode==='solo'&&state.activePlayer===1)return;if(mode==='online')command('fire');else{const weapon=state.equippedWeapons?.[state.activePlayer]||'shell',fired=fireProjectile(state);if(fired){saves?.markDirty();events.emit('battletanks:shot-fired',{weapon,side:state.activePlayer});if(mode==='solo')soloStatistics.shots+=1;}}sync();render();}fire.addEventListener('click',shoot);fullscreenFire.addEventListener('click',shoot);mobileFire.addEventListener('click',shoot);rematch.addEventListener('click',()=>{if(mode==='online')sendOnline({type:'rematch'});else{cancelAiTurn();saves?.startRun();resetMatch(state);resetSoloStatistics();lastImpactSerial=0;combatEffects=[];presentedResultEvent='';events.emit('game:started',{intensity:.32,danger:0,mode});}sync();render();});
const heldMovement=new Map(),movementAction=code=>code==='ArrowLeft'?moveAction('left'):code==='ArrowRight'?moveAction('right'):code==='KeyA'?'backward':code==='KeyD'?'forward':null;
function stopHeldMovement(code){const hold=heldMovement.get(code);if(!hold)return;clearTimeout(hold.delay);clearInterval(hold.interval);heldMovement.delete(code);}
function stopAllHeldMovement(){[...heldMovement.keys()].forEach(stopHeldMovement);}
