document.addEventListener('keydown',event=>{if(event.code==='Escape'&&currentPowerCard){event.preventDefault();dismissPowerCard();return;}if(currentPowerCard||['BUTTON','INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;if(movementAction(event.code)){event.preventDefault();startHeldMovement(event.code);return;}if(event.repeat)return;const actions={KeyW:'aim-up',KeyS:'aim-down',KeyQ:'power-down',KeyE:'power-up',ArrowUp:'aim-up',ArrowDown:'aim-down',Minus:'power-down',NumpadSubtract:'power-down',Equal:'power-up',NumpadAdd:'power-up'},action=actions[event.code];if(action){event.preventDefault();act(action);}else if(event.code==='Space'){event.preventDefault();shoot();}});
