function setupColorControls(){document.querySelectorAll('.player-color').forEach((picker,index)=>{const trigger=picker.querySelector('.color-trigger'),menu=picker.querySelector('.color-menu'),swatches=picker.querySelector('.swatches');trigger.style.setProperty('--selected-color',tankColors[index]);trigger.addEventListener('click',()=>{const opening=menu.hidden;document.querySelectorAll('.color-menu').forEach(item=>item.hidden=true);menu.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening));});window.ArcadeGameColors.forEach(color=>{const button=document.createElement('button');button.type='button';button.className='swatch';button.style.setProperty('--swatch',color.value);button.setAttribute('aria-label',`${color.name} Player ${index+1} tank`);button.setAttribute('aria-pressed',String(color.value===tankColors[index]));button.addEventListener('click',()=>{tankColors[index]=color.value;if(mode==='online'&&index===mySide)sendOnline({type:'color',color:color.value});trigger.style.setProperty('--selected-color',color.value);swatches.querySelectorAll('.swatch').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));menu.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.focus();render();});swatches.append(button);});});}
